332	     *  case); {@code exceptId} null checks against everyone, the person's own name and aliases too. */
333	    private void requireUnusedName(String sheetId, Long exceptId, String name) {
334	        boolean taken = people.findBySheetIdAndNameIgnoreCase(sheetId, name).stream()
335	                .anyMatch(p -> !p.getId().equals(exceptId))
336	                || !people.findBySheetIdAndAliasIgnoreCase(sheetId, name).isEmpty();
337	        if (taken) {
338	            throw nameInUse();
339	        }
340	    }
341	
342	    private static ResponseStatusException savedByAnother() {
343	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Saved by someone else since it was loaded");
344	    }
345	
346	    private static ResponseStatusException patronAlready() {
347	        return new ResponseStatusException(HttpStatus.CONFLICT, "Already a patron");
348	    }
349	
350	    private static ResponseStatusException contactInUse() {
351	        return new ResponseStatusException(HttpStatus.CONFLICT, "Contact already in use");
352	    }
353	
