34	@RestController
35	@RequestMapping("/api/sheets/{sheetId}/people")
36	@Validated
37	public class PersonController {
38	
39	    /** A person as the screen shows them, with their statement count and their last statement's
40	     *  due-total (two decimals; null when it was n/a or they have none) and date, and the date
41	     *  they are retired from (null while not retired), whether they have any hold, their holds, and the ids of
42	     *  their patrons in the order they were named, and whether the signed-in user watches them. The grade is the one in force on the sheet's
43	     *  today; grades lists every grade they have been given, by from-date, the first one undated; terms
44	     *  are their own terms in days (null when they have none). */
45	    public record PersonView(long id, String name, String grade, long version, int statementCount,
46	            String statedTotal, LocalDate statementDate, LocalDate retiredFrom, boolean held, List<Person.Hold> holds,
47	            List<Long> patronIds, List<Person.DatedGrade> grades, boolean watched, Integer terms,
48	            String contact, List<String> aliases) {
49	        public static PersonView of(Person p, LocalDate today, StatementSummary s, List<Long> patronIds,
50	                boolean watched) {
51	            return of(p.getId(), p, today, s, patronIds, watched);
52	        }
53	
54	        /** The person of the id, which a version rebuilt from the sheet's history does not carry. */
55	        static PersonView of(long id, Person p, LocalDate today, StatementSummary s, List<Long> patronIds,
56	                boolean watched) {
57	            return new PersonView(id, p.getName(), p.gradeOn(today), p.getVersion(), s.count(),
58	                    s.lastDueTotal() == null ? null : s.lastDueTotal().setScale(2).toPlainString(), s.lastDate(),
59	                    p.getRetiredFrom(), p.isHeld(), p.getHolds(), patronIds, p.getGrades(), watched, p.getTerms(),
60	                    p.getContact(), p.getAliases());
61	        }
62	    }
63	
64	    /** A person's values as the form submits them; the name is stored with surrounding spaces removed.
65	     *  An edit carries the version of the person its editor loaded, and the date its grade is in
66	     *  force from (null: the sheet's today); an add's grade is in force from the beginning of time.
67	     *  The terms are the person's own in whole days, blank or null for none. The contact is stored
68	     *  trimmed and lower-cased; blank or null for none. */
69	    public record PersonForm(
70	            @NotBlank @Size(max = 200) String name,
71	            @NotNull @Pattern(regexp = "[ABC]") String grade,
72	            Long version,
73	            LocalDate gradeFrom,
74	            @Pattern(regexp = "\\s*\\d{0,4}\\s*") String terms,
75	            @Size(max = 200) String contact) {
76	
77	        /** The terms in days; null when blank. */
78	        public Integer termsDays() {
79	            return terms == null || terms.isBlank() ? null : Integer.valueOf(terms.trim());
80	        }
81	
82	        /** The contact as stored: trimmed and lower-cased; null when blank. */
83	        public String contactValue() {
84	            return contact == null || contact.isBlank() ? null : contact.trim().toLowerCase(Locale.ROOT);
85	        }
86	    }
87	
88	    /** An alias as the row submits it; stored trimmed. */
89	    public record AliasForm(@Size(max = 200) String alias) {
90	    }
91	
92	    /** A retirement as the row submits it; a missing date takes the sheet's today. */
93	    public record RetireForm(LocalDate from) {
94	    }
95	
96	    /** A hold as the row submits it: a missing from-date takes the sheet's today; a missing to-date
97	     *  leaves it open-ended. */
98	    public record HoldForm(LocalDate from, LocalDate to) {
99	    }
100	
101	    /** A watch as the row submits it: true to start watching, false to stop. */
102	    public record WatchForm(@NotNull Boolean on) {
103	    }
104	
105	    /** A patron as the row submits it: the id of another person on the sheet. */
106	    public record PatronForm(@NotNull Long patronId) {
107	    }
108	
109	    /** A bulk grade as the screen submits it: the selected people by id, the grade, and the date it
110	     *  is in force from (null: the sheet's today). */
111	    public record BulkGradeForm(
112	            @NotNull @Size(min = 1, max = 10000) List<@NotNull Long> ids,
113	            @NotNull @Pattern(regexp = "[ABC]") String grade,
114	            LocalDate from) {
115	    }
116	
117	    /** A bulk grade's result: how many people were given the grade. */
118	    public record BulkGradeView(int changed) {
119	    }
120	
121	    private final PersonService service;
122	    private final HistoryService history;
123	    private final SettingsService settings;
124	    private final SheetService sheets;
125	
126	    public PersonController(PersonService service, HistoryService history, SettingsService settings, SheetService sheets) {
127	        this.service = service;
128	        this.history = history;
129	        this.settings = settings;
130	        this.sheets = sheets;
131	    }
132	
133	    @GetMapping
134	    public List<PersonView> list(
135	            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
136	            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
137	            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
138	        if (asOf != null) {
139	            HistoryService.AsOf then = history.asOf(sheetId, asOf);
140	            return then.people().keySet().stream().map(id -> viewAsOf(then, asOf, user, id)).toList();
141	        }
142	        Map<Long, StatementSummary> summaries = service.statementSummaries(sheetId);
143	        Map<Long, List<Long>> patrons = service.patronIds(sheetId);
144	        LocalDate today = service.today(sheetId);
145	        Set<Long> watched = service.watchedIds(sheetId, user.trim());
146	        return service.list(sheetId).stream()
147	                .map(p -> PersonView.of(p, today, summaries.getOrDefault(p.getId(), StatementSummary.NONE),
148	                        patrons.getOrDefault(p.getId(), List.of()), watched.contains(p.getId())))
149	                .toList();
150	    }
151	
152	    @GetMapping("/{id}")
153	    public PersonView get(
154	            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
155	            @PathVariable long id,
156	            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
157	            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
158	        if (asOf != null) {
159	            HistoryService.AsOf then = history.asOf(sheetId, asOf);
160	            if (!then.people().containsKey(id)) {
161	                throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person");
162	            }
163	            return viewAsOf(then, asOf, user, id);
164	        }
165	        return view(sheetId, user, service.get(sheetId, id));
166	    }
167	
168	    @PostMapping
