38	    private Long id;
39	
40	    @Column(name = "sheet_id", nullable = false)
41	    private String sheetId;
42	
43	    @Column(name = "name", nullable = false)
44	    private String name;
45	
46	    /** The first grade the person was given: in force from the beginning of time until a later one. */
47	    @Column(name = "grade", nullable = false)
48	    private String grade;
49	
50	    /** The grades recorded since, by the date each is in force from. */
51	    @ElementCollection(fetch = FetchType.EAGER)
52	    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
53	    @MapKeyColumn(name = "from_date")
54	    @Column(name = "grade", nullable = false)
55	    private Map<LocalDate, String> datedGrades = new HashMap<>();
56	
57	    /** The person's own terms in days, ahead of their grade's and the sheet's; null when they have none. */
58	    @Column(name = "terms")
59	    private Integer terms;
60	
61	    /** The person's contact, trimmed and lower-cased; null when they have none. */
62	    @Column(name = "contact")
63	    private String contact;
64	
65	    /** The person's aliases, kept trimmed: other names the person is found by. */
66	    @ElementCollection(fetch = FetchType.EAGER)
67	    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
68	    @Column(name = "alias", nullable = false)
69	    private Set<String> aliases = new HashSet<>();
70	
71	    /** The date the person is retired from; null while not retired. Set, they count as retired
72	     *  at once, whatever the date. */
73	    @Column(name = "retired_from")
74	    private LocalDate retiredFrom;
75	
76	    /** The person's holds, in the order they were added: their OPEN claims dated within one count
77	     *  in no live total (unless bound by a statement). */
78	    @ElementCollection(fetch = FetchType.EAGER)
79	    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
80	    @OrderColumn(name = "position")
81	    private List<Hold> holds = new ArrayList<>();
82	
83	    /** Raised on every save, so an edit of a version someone else has since saved is refused. */
84	    @Version
85	    @Column(name = "version", nullable = false)
86	    private long version;
87	
88	    protected Person() {
89	    }
90	
91	    public Person(String sheetId, String name, String grade) {
92	        this.sheetId = sheetId;
93	        this.name = name;
94	        this.grade = grade;
95	    }
96	
97	    public Long getId() {
98	        return id;
99	    }
100	
101	    public String getSheetId() {
102	        return sheetId;
103	    }
104	
105	    public String getName() {
106	        return name;
107	    }
108	
109	    public void setName(String name) {
110	        this.name = name;
111	    }
112	
113	    /** A grade and the date it is in force from (null: from the beginning of time). */
114	    public record DatedGrade(String grade, LocalDate from) {
115	    }
116	
117	    /** The grade in force on a date: the one with the latest from-date on or before it, else the first. */
118	    public String gradeOn(LocalDate on) {
119	        Map.Entry<LocalDate, String> latest = new TreeMap<>(datedGrades).floorEntry(on);
120	        return latest == null ? grade : latest.getValue();
121	    }
122	
123	    /** Record a grade from a date, in place of any recorded from the same date. */
124	    public void recordGrade(String grade, LocalDate from) {
125	        datedGrades.put(from, grade);
126	    }
127	
128	    /** Every grade the person has been given, by from-date, the first one (undated) leading. */
129	    public List<DatedGrade> getGrades() {
130	        List<DatedGrade> out = new ArrayList<>();
131	        out.add(new DatedGrade(grade, null));
132	        new TreeMap<>(datedGrades).forEach((from, g) -> out.add(new DatedGrade(g, from)));
133	        return out;
134	    }
135	
136	    public Integer getTerms() {
137	        return terms;
138	    }
139	
140	    public void setTerms(Integer terms) {
141	        this.terms = terms;
142	    }
143	
144	    public String getContact() {
145	        return contact;
146	    }
147	
148	    public void setContact(String contact) {
149	        this.contact = contact;
150	    }
151	
152	    /** The person's aliases, sorted as names are compared (ignoring case). */
153	    public List<String> getAliases() {
154	        return aliases.stream()
155	                .sorted(Comparator.comparing((String a) -> a.toLowerCase(Locale.ROOT)).thenComparing(a -> a))
156	                .toList();
157	    }
158	
159	    public void addAlias(String alias) {
160	        aliases.add(alias);
161	    }
162	
163	    /** Whether the name or one of the aliases equals {@code name}, as names are compared. */
164	    public boolean goesBy(String name) {
165	        return this.name.equalsIgnoreCase(name) || aliases.stream().anyMatch(a -> a.equalsIgnoreCase(name));
166	    }
167	
168	    public LocalDate getRetiredFrom() {
169	        return retiredFrom;
170	    }
171	
172	    public void setRetiredFrom(LocalDate retiredFrom) {
173	        this.retiredFrom = retiredFrom;
174	    }
175	
176	    public boolean isRetired() {
177	        return retiredFrom != null;
178	    }
179	
180	    /** Whether a claim dated {@code date} is refused for the person: one after their retirement date. */
181	    public boolean retiredBefore(LocalDate date) {
182	        return retiredFrom != null && date.isAfter(retiredFrom);
183	    }
184	
185	    /** Whether the person's retirement date is reached on {@code today} (on or after it): their
