679	   *  would show a different due were a percent that grade's rate on every date, and the differences
680	   *  (new due minus current due) added up in cents; a claim bound by a statement does not change. */
681	  protected readonly previewRate = (grade: string, pct: string): RatePreview => {
682	    const late = this.lateness();
683	    const candidate: Rate[] = [{ grade, from: null, to: null, pct }];
684	    let count = 0;
685	    let diff = 0;
686	    for (const p of this.people()) {
687	      for (const c of this.claimsOf(p.id)) {
688	        if ((c.status !== 'OPEN' && c.status !== 'PENDING') || isBound(c) || gradeOn(p.grades, c.date) !== grade) continue;
689	        const now = this.claimDueCents(p, c, late);
690	        const next = this.claimDueCents(p, c, late, candidate);
691	        if (now === next) continue;
692	        count++;
693	        diff += (next ?? 0) - (now ?? 0);
694	      }
695	    }
696	    return { count, cents: diff };
